PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?zone ?point ?cls WHERE {
  ?zone brick:hasPoint ?point .
  FILTER (STRSTARTS(STR(?zone), "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z01"))
  OPTIONAL{ ?point ?p ?x FILTER(?p=ref:hasExternalReference) }
  ?point ?t ?cls .
  FILTER(?t = <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> )
}

